questionvariables.text:
/* Length of shed */
L: rand(8)+6;          /* 6..13 m */

/* Width of shed */
w: rand(5)+4;          /* 4..8 m */

/* Height of rectangular walls */
h_wall: rand(4)+2;     /* 2..5 m */

/* Height of triangular roof */
h_roof: rand(4)+1;     /* 1..4 m */

/* Volume of rectangular prism */
V_rect: L*w*h_wall;

/* Area of triangular cross-section */
A_roof: (w*h_roof)/2;

/* Volume of triangular prism roof */
V_roof: A_roof*L;

/* Total volume */
ta: V_rect + V_roof;

/* Rounded answer (2 d.p. if required) */
ta2dp: float(round(100*ev(ta,numer))/100);

/* Common mistakes */

/* Rectangular prism only */
wrong_rect_only: V_rect;

/* Roof only */
wrong_roof_only: V_roof;

/* Forgot ÷2 in triangle area */
wrong_no_half: (w*h_roof)*L + V_rect;

/* Added dimensions */
wrong_addition: L+w+h_wall+h_roof;

/* Useful values */
cross_section_area: A_roof;
